"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["16857"],{3555(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.requisicao.campo_obrigatorio_ausente","status":400,"titulo":"A requisi\xe7\xe3o n\xe3o declara campo obrigat\xf3rio do contrato"},"descricao":{"codigo":"uniplus.requisicao.campo_obrigatorio_ausente","requisitos":[],"oQueAconteceu":["A requisi\xe7\xe3o n\xe3o trouxe um campo exigido pela opera\xe7\xe3o. O campo `detail` da resposta informa o nome do que falta.","A aus\xeancia tem duas origens, e as duas caem aqui:","1. **Campo obrigat\xf3rio do corpo.** O documento chegou e foi lido, mas n\xe3o cont\xe9m uma propriedade obrigat\xf3ria.\\n2. **Par\xe2metro fora do corpo.** A requisi\xe7\xe3o n\xe3o trouxe um valor exigido na consulta, no cabe\xe7alho ou no formul\xe1rio.","O `detail` traz apenas os nomes dos campos, e nada do texto que o framework\\nproduziu ao recusar. Essa mensagem carrega o nome completo do tipo interno que\\nreceberia o documento \u2014 namespace e camada da aplica\xe7\xe3o \u2014, e repass\xe1-la\\npublicaria estrutura interna a qualquer cliente que mandasse uma carga\\nincompleta.","Quando h\xe1 campo nome\xe1vel faltando, esta causa prevalece sobre as demais recusas\\nde leitura da requisi\xe7\xe3o: dizer o que falta \xe9 a orienta\xe7\xe3o mais \xfatil que a\\nresposta consegue dar."],"comoResolver":["Acrescente \xe0 requisi\xe7\xe3o os campos indicados em `detail` e repita a chamada. A refer\xeancia de API do m\xf3dulo informa os campos obrigat\xf3rios e seus nomes para cada opera\xe7\xe3o.","Se o campo foi declarado e ainda assim a requisi\xe7\xe3o \xe9 recusada, a causa \xe9\\noutra:","- Um valor do documento incompat\xedvel com o tipo esperado recebe [requisi\xe7\xe3o malformada](/erros/uniplus.requisicao.malformada).\\n- Um par\xe2metro fora do corpo \u2014 no caminho, na consulta, no cabe\xe7alho ou no formul\xe1rio \u2014 com tipo incompat\xedvel recebe [valor inv\xe1lido](/erros/uniplus.requisicao.valor_invalido).\\n- Uma requisi\xe7\xe3o sem documento recebe [corpo ausente](/erros/uniplus.requisicao.corpo_ausente)."],"ondeAparece":["Opera\xe7\xf5es com campo obrigat\xf3rio ausente na requisi\xe7\xe3o"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Requisicao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"fd5ea0ff72951399d2b2c1a4f29aeb3ea415db44"}}')}}]);